-- STA 112: Introductory Probability
-- =============================================================================
-- 88 questions. Sources: the STA 112 typed notes and expanded study guides (sets,
-- counting, probability rules, random variables and distributions) and the
-- STA 112 practice set (65 items). Every answer was recomputed. Corrections to
-- the practice set's printed key: committee count (4704, not 432), 12C5 = 792
-- (the printed options had no 792, so the options were rebuilt), independence of
-- A and B (independent, not mutually exclusive), sum of 8 on two dice (5/36),
-- and the exactly-one-alive wording. Three items whose text or options were
-- illegible were dropped. The textbooks (Schaum, NOUN STT 211, Grinstead and
-- Snell) were not copied; all stems are original. Obasi's notes were not used.
-- ASSUMPTIONS (please confirm): 100 Level, second semester, 3 units; faculties
-- Physical Sciences, Engineering, Social Sciences, Biological Sciences.
-- =============================================================================
delete from public.cbt_questions where subject_id in ('sta-112-coming-soon', 'sta-112-introductory-probability');

insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general,
   semester, units)
values
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'An aggregate of elements having certain specified properties is called:', '["a set","a subset","an integer","a probability"]'::jsonb, 0, 'A set is a well-defined collection of objects (elements).', 'Set Theory', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The number of subsets in the power set of a set with 4 elements is:', '["8","16","4","24"]'::jsonb, 1, 'A set with $n$ elements has $2^{n}$ subsets, so $2^{4} = 16$.', 'Power Set', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'If $|A| = 12$, $|B| = 9$ and $|A \cap B| = 5$, then $|A \cup B|$ is:', '["21","26","16","14"]'::jsonb, 2, '$|A \cup B| = |A| + |B| - |A \cap B| = 12 + 9 - 5 = 16$.', 'Set Operations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'By De Morgan''s law, $(A \cup B)''$ equals:', '["$A'' \\cup B''$","$A \\cap B$","$A \\cup B$","$A'' \\cap B''$"]'::jsonb, 3, 'The complement of a union is the intersection of the complements.', 'Laws of the Algebra of Sets', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'If set $A$ has 3 elements and set $B$ has 4 elements, the Cartesian product $A \times B$ has how many ordered pairs?', '["12","7","3","81"]'::jsonb, 0, '$|A \times B| = |A||B| = 3 \times 4 = 12$.', 'Cartesian Product', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Two sets are disjoint when:', '["one is a subset of the other","they have no element in common","they have exactly one element in common","their union is empty"]'::jsonb, 1, 'Disjoint sets satisfy $A \cap B = \varnothing$.', 'Set Theory', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The set difference $A - B$ consists of:', '["elements that belong to both $A$ and $B$","elements that belong to $B$ but not to $A$","elements that belong to $A$ but not to $B$","all elements of $A$ and $B$"]'::jsonb, 2, 'It is $A \cap B^{\prime}$.', 'Set Operations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The probability of an impossible event is:', '["1","1/2","1.6","0"]'::jsonb, 3, 'An event that cannot occur has probability 0; a certain event has probability 1.', 'Basic Probability', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The sum of the probability of success and the probability of failure in a trial is:', '["1","0","1/2","2"]'::jsonb, 0, '$p + q = 1$.', 'Basic Probability', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'If $P(A) = 0.35$, then $P(A^{\prime})$ is:', '["0.35","0.65","0.45","1.35"]'::jsonb, 1, '$P(A^{\prime}) = 1 - P(A) = 0.65$.', 'Basic Probability', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Two events are mutually exclusive if:', '["$P(A \\cap B) = P(A)P(B)$","$P(A \\cup B) = 1$","$P(A \\cap B) = 0$","$P(A) = P(B)$"]'::jsonb, 2, 'They cannot occur together.', 'Types of Events', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Selecting $r$ objects out of $n$ without regard to order is called:', '["a permutation","a factorial","replacement","a combination"]'::jsonb, 3, 'Order does not matter in a combination, ${}^{n}C_{r}$.', 'Counting Techniques', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The value of ${}^{9}P_{3}$ is:', '["504","84","729","27"]'::jsonb, 0, '${}^{9}P_{3} = 9 \times 8 \times 7 = 504$.', 'Permutations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The value of ${}^{12}C_{5}$ is:', '["729","792","95040","60"]'::jsonb, 1, '${}^{12}C_{5} = \dfrac{12!}{5!\,7!} = 792$.', 'Combinations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'In how many ways can the letters of the word WORLD be arranged?', '["25","50","120","100"]'::jsonb, 2, 'Five distinct letters: $5! = 120$.', 'Permutations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'In how many ways can the letters of the word BOOK be arranged?', '["24","6","2","12"]'::jsonb, 3, 'Four letters with O repeated twice: $\dfrac{4!}{2!} = 12$.', 'Permutations with Repetition', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The number of arrangements of the letters of the word CALCULUS is:', '["5040","240","3600","120"]'::jsonb, 0, 'Eight letters with C, L and U each repeated twice: $\dfrac{8!}{2!\,2!\,2!} = 5040$.', 'Permutations with Repetition', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The number of distinct arrangements of the letters of MISSISSIPPI is:', '["39916800","34650","3465","5040"]'::jsonb, 1, '$\dfrac{11!}{4!\,4!\,2!} = 34650$ (I four times, S four times, P twice).', 'Permutations with Repetition', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'How many 5-letter code words can be formed from the letters of the word MATRICES (all letters distinct)?', '["4500","2410","6720","4212"]'::jsonb, 2, '${}^{8}P_{5} = 8\times7\times6\times5\times4 = 6720$.', 'Permutations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'In how many ways can 9 people be seated if only 3 chairs are available?', '["501","502","503","504"]'::jsonb, 3, '${}^{9}P_{3} = 504$.', 'Permutations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'There are six seats in a railway carriage. In how many different ways can four people occupy them?', '["360","240","120","320"]'::jsonb, 0, '${}^{6}P_{4} = 6\times5\times4\times3 = 360$.', 'Permutations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'If $n$ items are arranged two at a time, the number of arrangements is 20. The value of $n$ is:', '["10","5","15","4"]'::jsonb, 1, '$n(n-1) = 20$ gives $n = 5$.', 'Permutations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Find the positive value of $n$ if $3\left({}^{n}P_{2} + 24\right) = {}^{2n}P_{2}$.', '["6","7","8","9"]'::jsonb, 2, '$3[n(n-1) + 24] = 2n(2n-1)$ simplifies to $n^{2} + n - 72 = 0$, so $n = 8$.', 'Permutations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'In how many ways can 8 men be seated at a round table if 2 particular men refuse to sit together?', '["342","543","450","3600"]'::jsonb, 3, 'Total circular arrangements $= 7! = 5040$. Treating the two men as one block gives $2\times6! = 1440$. So $5040 - 1440 = 3600$.', 'Circular Permutations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'In how many ways can 6 people be seated around a circular table?', '["120","720","24","60"]'::jsonb, 0, 'Circular permutations of $n$ objects: $(n-1)! = 120$.', 'Circular Permutations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A committee of 4 boys and 3 girls is to be formed from 10 boys and 8 girls, with one particular boy who must be on it. In how many ways can this be done?', '["432","4704","456","4531"]'::jsonb, 1, 'The chosen boy fills one place; choose 3 more boys from 9 and 3 girls from 8: ${}^{9}C_{3}\times{}^{8}C_{3} = 84 \times 56 = 4704$.', 'Combinations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A test has 12 questions, of which candidates answer 10. If the first 6 are compulsory, in how many ways can a candidate choose the questions?', '["40","25","15","10"]'::jsonb, 2, 'The 6 compulsory ones are fixed; choose 4 more from the remaining 6: ${}^{6}C_{4} = 15$.', 'Combinations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Simplify ${}^{12}C_{10} + {}^{12}C_{9}$.', '["259","345","540","286"]'::jsonb, 3, '${}^{12}C_{10} = 66$ and ${}^{12}C_{9} = 220$, so the sum is 286 (which equals ${}^{13}C_{10}$).', 'Combinations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'In how many ways can 5 footballers be selected from a team of 12 players?', '["792","432","342","729"]'::jsonb, 0, '${}^{12}C_{5} = 792$.', 'Combinations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'From 5 statisticians and 6 economists, a committee of 3 statisticians and 2 economists is to be formed. If two particular statisticians must NOT be on the committee, how many committees are possible?', '["100","15","150","30"]'::jsonb, 1, 'Only 3 statisticians remain, so choose all 3 and 2 of the 6 economists: $1 \times {}^{6}C_{2} = 15$.', 'Combinations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'At a meeting each of 8 people shakes hands once with every other person. The number of handshakes is:', '["56","64","28","16"]'::jsonb, 2, '${}^{8}C_{2} = 28$.', 'Combinations', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The coefficient of $x^{2}$ in the expansion of $(1 + x)^{5}$ is:', '["5","20","25","10"]'::jsonb, 3, 'By the binomial theorem the coefficient is ${}^{5}C_{2} = 10$.', 'Binomial Theorem', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The sum of all the binomial coefficients in the expansion of $(1 + x)^{6}$ is:', '["64","36","12","6"]'::jsonb, 0, 'Setting $x = 1$ gives $2^{6} = 64$.', 'Binomial Theorem', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Stirling''s approximation for $n!$ with large $n$ is:', '["$n! \\approx n^{n}$","$n! \\approx \\sqrt{2\\pi n}\\,(n/e)^{n}$","$n! \\approx 2^{n}$","$n! \\approx n\\,e^{n}$"]'::jsonb, 1, 'It is useful for evaluating very large factorials.', 'Stirling''s Approximation', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'In a class of 100 students, 50 study geography, 40 study mathematics and 20 study both. The probability that a student chosen at random studies neither is:', '["0.5","0.8","0.3","0.9"]'::jsonb, 2, '$|G \cup M| = 50 + 40 - 20 = 70$, so $P(\text{neither}) = 30/100 = 0.3$.', 'Basic Probability', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The probabilities that a man and his wife will be alive in 20 years are 0.6 and 0.7. The probability that exactly one of them will be alive is:', '["0.56","0.23","0.65","0.46"]'::jsonb, 3, 'Exactly one alive: man alive and wife not, or wife alive and man not. $0.6(0.3) + 0.4(0.7) = 0.18 + 0.28 = 0.46$.', 'Multiplication Rule', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A packet contains 5 red, 7 blue and 6 green pens. The probability of picking a white pen is:', '["0","1/8","1/2","1/4"]'::jsonb, 0, 'There are no white pens, so the event is impossible.', 'Basic Probability', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A basket has 6 grapes, 11 bananas and 13 oranges. One fruit is picked at random. The probability that it is a grape or a banana is:', '["11/30","17/30","12/33","11/15"]'::jsonb, 1, '$(6 + 11)/30 = 17/30$.', 'Additive Rule', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A fair die is tossed twice. The probability that the total score is 8 or 11 is:', '["5/36","3/36","7/36","1/36"]'::jsonb, 2, 'A sum of 8 occurs in 5 ways and a sum of 11 in 2 ways: $(5 + 2)/36 = 7/36$.', 'Additive Rule', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A fair die is tossed twice. The probability that the total score is at least 3 is:', '["3/36","7/36","1/36","35/36"]'::jsonb, 3, 'The only total below 3 is 2 (one way), so the probability is $1 - 1/36 = 35/36$.', 'Basic Probability', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Two fair dice are thrown. The probability that the sum is 8 is:', '["5/36","1/6","5/6","7/36"]'::jsonb, 0, 'The favourable outcomes are (2,6), (3,5), (4,4), (5,3) and (6,2): 5 out of 36.', 'Basic Probability', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Three applicants succeed at an interview with probabilities 1/3, 2/3 and 1/4 respectively. The probability that all three are successful is:', '["5/18","1/18","7/18","11/18"]'::jsonb, 1, 'The events are independent: $\tfrac{1}{3}\times\tfrac{2}{3}\times\tfrac{1}{4} = \tfrac{2}{36} = \tfrac{1}{18}$.', 'Multiplication Rule', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'If $A$ and $B$ are mutually exclusive with $P(A) = 3/4$ and $P(B) = 1/6$, then $P(A \cup B)$ is:', '["5/12","7/8","11/12","1/8"]'::jsonb, 2, 'For mutually exclusive events probabilities add: $\tfrac{3}{4} + \tfrac{1}{6} = \tfrac{11}{12}$.', 'Additive Rule', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For mutually exclusive events with $P(A) = 0.4$ and $P(B) = 0.3$, $P(A \text{ or } B)$ is:', '["0.6","0.58","0.75","0.7"]'::jsonb, 3, '$0.4 + 0.3 = 0.7$.', 'Additive Rule', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'If $P(A) = 2/3$, $P(B) = 3/5$ and $P(A \cup B) = 13/15$, the events $A$ and $B$ are:', '["independent","mutually exclusive","exhaustive","equally likely"]'::jsonb, 0, '$P(A\cap B) = \tfrac{2}{3} + \tfrac{3}{5} - \tfrac{13}{15} = \tfrac{2}{5} = P(A)P(B)$, so they are independent.', 'Independent Events', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'If $A$ and $B$ are independent with $P(A) = 0.3$ and $P(B) = 0.4$, then $P(A \cup B)$ is:', '["0.70","0.58","0.12","0.82"]'::jsonb, 1, '$P(A\cup B) = P(A) + P(B) - P(A)P(B) = 0.3 + 0.4 - 0.12 = 0.58$.', 'Additive Rule', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'If $P(A \cap B) = 0.2$ and $P(B) = 0.5$, the conditional probability $P(A \mid B)$ is:', '["0.1","0.7","0.4","2.5"]'::jsonb, 2, '$P(A\mid B) = P(A\cap B)/P(B) = 0.2/0.5 = 0.4$.', 'Conditional Probability', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A fair coin is tossed twice. The probability of at least one head is:', '["1/4","1/2","1","3/4"]'::jsonb, 3, '$1 - P(\text{no head}) = 1 - 1/4 = 3/4$.', 'Basic Probability', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'One card is drawn from a standard pack of 52. The probability that it is a king or a heart is:', '["4/13","17/52","1/2","3/13"]'::jsonb, 0, '$P(K) + P(H) - P(K\cap H) = \tfrac{4}{52} + \tfrac{13}{52} - \tfrac{1}{52} = \tfrac{16}{52} = \tfrac{4}{13}$.', 'Additive Rule', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A bag holds 5 red and 3 blue balls. Two balls are drawn without replacement. The probability that both are red is:', '["25/64","5/14","5/8","1/4"]'::jsonb, 1, '$\tfrac{5}{8}\times\tfrac{4}{7} = \tfrac{20}{56} = \tfrac{5}{14}$.', 'Multiplication Rule', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The probability of getting a number not greater than 6 on a fair die is:', '["0","1/3","1","1/6"]'::jsonb, 2, 'Every outcome is at most 6, so the event is certain.', 'Basic Probability', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Urn 1 holds 3 red and 2 blue balls; urn 2 holds 1 red and 4 blue. An urn is chosen at random and one ball is drawn. The probability that the ball is red is:', '["0.5","0.4","0.3","0.4"]'::jsonb, 3, 'Total probability: $0.5(0.6) + 0.5(0.2) = 0.4$.', 'Total Probability', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'In that experiment, given that the ball drawn is red, the probability that it came from urn 1 is:', '["0.75","0.60","0.50","0.25"]'::jsonb, 0, 'Bayes'' theorem: $\dfrac{0.5(0.6)}{0.5(0.6) + 0.5(0.2)} = \dfrac{0.3}{0.4} = 0.75$.', 'Bayes'' Theorem', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Bayes'' theorem is used to:', '["count the number of arrangements","revise a probability in the light of new information","find the mean of a binomial variable","calculate the power of a test"]'::jsonb, 1, 'It converts $P(B\mid A)$ into $P(A\mid B)$ using prior probabilities.', 'Bayes'' Theorem', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A random variable that takes a finite or countable number of values is called:', '["a continuous random variable","a qualitative variable","a discrete random variable","a constant"]'::jsonb, 2, 'Counts such as the number of heads are discrete.', 'Random Variables', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Two types of quantitative random variable are:', '["sample space and event space","set and subset","qualitative and quantitative","discrete and continuous"]'::jsonb, 3, 'A quantitative variable is either discrete or continuous.', 'Random Variables', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Which of the following is a discrete probability distribution?', '["Poisson distribution","Normal distribution","Exponential distribution","Beta distribution"]'::jsonb, 0, 'The Poisson variable counts events, taking values 0, 1, 2, ...', 'Probability Distributions', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Which of the following is a continuous probability distribution?', '["Binomial distribution","Normal distribution","Poisson distribution","Hypergeometric distribution"]'::jsonb, 1, 'The normal variable takes any real value.', 'Probability Distributions', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For a discrete probability distribution, the sum of all the probabilities is:', '["0","less than 1","1","infinite"]'::jsonb, 2, '$\sum P(x) = 1$.', 'Probability Distributions', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For a continuous random variable $X$, the function $f(x)$ is called the:', '["probability mass function","marginal function","cumulative function","probability density function"]'::jsonb, 3, 'A discrete variable has a probability mass function.', 'Probability Distributions', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The two parameters of a binomial distribution are:', '["$n$ and $p$","$\\mu$ and $\\sigma^{2}$","$\\mu$ and $p$","$p$ and $q$"]'::jsonb, 0, '$n$ is the number of trials and $p$ the probability of success.', 'Binomial Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The mean of a binomial distribution with parameters $n$ and $p$ is:', '["$npq$","$np$","$n(n-1)pq$","$pq$"]'::jsonb, 1, 'The variance is $npq$.', 'Binomial Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A fair die is thrown five times. The probability of getting exactly one six is:', '["0.3564","0.7854","0.4019","0.0234"]'::jsonb, 2, '$\binom{5}{1}\left(\tfrac{1}{6}\right)\left(\tfrac{5}{6}\right)^{4} = 0.4019$.', 'Binomial Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A fair coin is tossed six times. The probability of exactly four heads is:', '["0.5742","0.5673","0.4532","0.2344"]'::jsonb, 3, '$\binom{6}{4}\left(\tfrac{1}{2}\right)^{6} = \tfrac{15}{64} = 0.2344$.', 'Binomial Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For $X \sim \text{Bin}(10, 0.3)$, $P(X = 3)$ is:', '["0.2668","0.3000","0.0900","0.5000"]'::jsonb, 0, '$\binom{10}{3}(0.3)^{3}(0.7)^{7} = 0.2668$.', 'Binomial Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For $X \sim \text{Bin}(10, 0.3)$, the variance is:', '["3.0","2.1","7.0","0.21"]'::jsonb, 1, '$npq = 10(0.3)(0.7) = 2.1$.', 'Binomial Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A binomial variable has mean 8 and variance 6. The parameters $n$ and $p$ are:', '["$n = 28,\\ p = 0.25$","$n = 30,\\ p = 0.5$","$n = 32,\\ p = 0.25$","$n = 31,\\ p = 0.5$"]'::jsonb, 2, '$npq = 6$ and $np = 8$ give $q = 0.75$, $p = 0.25$ and $n = 32$.', 'Binomial Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'If a die is thrown five times, the variance of the number of sixes is:', '["0.1667","0.8333","0.6754","0.6944"]'::jsonb, 3, '$npq = 5\times\tfrac{1}{6}\times\tfrac{5}{6} = 0.6944$.', 'Binomial Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Which distribution has its mean and variance both equal to $\lambda$?', '["Poisson","Exponential","Normal","Geometric"]'::jsonb, 0, 'For a Poisson variable, $E(X) = \mathrm{Var}(X) = \lambda$.', 'Poisson Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A Poisson variable has mean 2. The probability that $X = 0$ is:', '["0.2707","0.1353","0.5000","0.3679"]'::jsonb, 1, '$P(X=0) = e^{-2} = 0.1353$.', 'Poisson Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For a Poisson variable with mean 2, $P(X = 2)$ is:', '["0.1353","0.2240","0.2707","0.1804"]'::jsonb, 2, '$P(X=2) = \dfrac{e^{-2}2^{2}}{2!} = 0.2707$.', 'Poisson Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A random variable $X$ has density $f(x) = 3x^{2}$ for $0 < x < 1$ and 0 otherwise. The mean of $X$ is:', '["1/3","2/3","4/3","3/4"]'::jsonb, 3, '$E(X) = \int_{0}^{1} x\cdot3x^{2}\,dx = \tfrac{3}{4}$.', 'Continuous Random Variables', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The variance of a random variable $X$ is given by:', '["$E(X^{2}) - [E(X)]^{2}$","$[E(X)]^{2} - E(X^{2})$","$E(X) - E(X^{2})$","$E(X)^{2}$"]'::jsonb, 0, 'Variance $= E(X^{2}) - \mu^{2}$.', 'Expectation and Variance', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A discrete variable takes the values 1, 2, 3 with probabilities 0.2, 0.5, 0.3. Its expected value is:', '["2.0","2.1","1.8","2.3"]'::jsonb, 1, '$E(X) = 1(0.2) + 2(0.5) + 3(0.3) = 2.1$.', 'Expectation and Variance', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For the same distribution, the variance is:', '["4.90","2.10","0.49","0.70"]'::jsonb, 2, '$E(X^{2}) = 0.2 + 2.0 + 2.7 = 4.9$, so $\mathrm{Var}(X) = 4.9 - 2.1^{2} = 0.49$.', 'Expectation and Variance', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Let $X$ be the number of heads when two fair coins are tossed. $\mathrm{Var}(X)$ is:', '["1/4","1/8","3/4","1/2"]'::jsonb, 3, '$X \sim \text{Bin}(2, \tfrac{1}{2})$, so $\mathrm{Var}(X) = 2\cdot\tfrac{1}{2}\cdot\tfrac{1}{2} = \tfrac{1}{2}$.', 'Expectation and Variance', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Which statement about the distribution function $F(x)$ is NOT correct?', '["$F(x)$ is a non-increasing function of $x$","$F(-\\infty) = 0$","$F(\\infty) = 1$","$0 \\leq F(x) \\leq 1$"]'::jsonb, 0, 'A distribution function is non-decreasing, so the "non-increasing" statement is false.', 'Distribution Function', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Which of these is NOT a characteristic of a normal distribution?', '["it is symmetrical about the mean","the curve is multimodal","mean = median = mode","it is bell-shaped"]'::jsonb, 1, 'A normal curve has a single peak (unimodal).', 'Normal Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The normal distribution is also called the:', '["gamma distribution","beta distribution","Gaussian distribution","Weibull distribution"]'::jsonb, 2, 'It is named after Carl Friedrich Gauss.', 'Normal Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For the standard normal variable $Z$, $P(Z < -1.00)$ is:', '["0.84134","0.1552","0.8289","0.15866"]'::jsonb, 3, '$P(Z < -1) = 1 - P(Z < 1) = 1 - 0.84134 = 0.15866$.', 'Normal Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For the standard normal variable, $P(Z < 1.96)$ is approximately:', '["0.975","0.950","0.995","0.900"]'::jsonb, 0, 'The 97.5th percentile of the standard normal distribution is 1.96.', 'Normal Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The standard normal distribution has:', '["mean 1 and variance 0","mean 0 and variance 1","mean 0 and variance 0","mean 1 and variance 1"]'::jsonb, 1, '$Z = (X - \mu)/\sigma$ is standardised to mean 0 and variance 1.', 'Normal Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A bell-shaped distribution of a random variable $X$ is a:', '["discrete distribution","binomial distribution","normal distribution","uniform distribution"]'::jsonb, 2, 'The graph of the normal density is the normal curve.', 'Normal Distribution', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A numerical value computed from sample data is called a:', '["parameter","census","population","statistic"]'::jsonb, 3, 'A parameter describes a population; a statistic describes a sample.', 'Sampling Basics', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A numerical characteristic of a population is called a:', '["parameter","statistic","sample","estimator"]'::jsonb, 0, 'The population mean $\mu$ is a parameter.', 'Sampling Basics', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The difference between a population parameter and the estimate computed from a sample is called:', '["transcription error","sampling error","biased error","measurement error"]'::jsonb, 1, 'It arises because only part of the population is observed.', 'Sampling Basics', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A population contains the numbers 2, 5 and 8. The population mean is:', '["3","2","5","4"]'::jsonb, 2, '$(2 + 5 + 8)/3 = 5$.', 'Sampling Basics', false, 'second', 3),
  ('sta-112-introductory-probability', 'STA 112: Introductory Probability', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For a population of size $N$, the number of possible samples of size $n$ drawn WITH replacement is:', '["$\\binom{N}{n}$","$N!$","$n^{N}$","$N^{n}$"]'::jsonb, 3, 'Each of the $n$ draws can be any of $N$ values.', 'Sampling Basics', false, 'second', 3);

